/**
 * Platform-neutral sticker state. Coordinates remain in the layout's world space.
 * A native touch adapter and renderer own hit testing, camera motion and animation;
 * only commitPlacement(ticket), after animation, changes saved progress.
 */
export type AreaLevel = 'L1' | 'L2' | 'L3';
export type SessionPhase = 'playing' | 'placing' | 'transitioning' | 'completed';
export type LayoutRevision = string | number;
export interface Point { x: number; y: number }
export interface Size { width: number; height: number }
export interface RenderPart {
  partId: string;
  placementOrder: number;
  paintOrder?: number;
  layerIndex: number;
  offset: Point;
  [key: string]: unknown;
}
export interface RenderQueueEntry {
  kind: 'stickerPart' | 'fixed';
  stickerId?: string;
  partId?: string;
  fixedId?: string;
  placementOrder: number;
  paintOrder?: number;
  layerIndex: number;
  [key: string]: unknown;
}
export interface FixedPlacement {
  fixedId: string;
  placementOrder: number;
  paintOrder?: number;
  layerIndex: number;
  [key: string]: unknown;
}
export interface GeoBlock {
  blockId: string;
  blockOrder: number;
  [key: string]: unknown;
}
export interface StickerPlacement {
  stickerId: string;
  geoBlock: string;
  areaLevel: AreaLevel;
  placementOrder: number;
  layerIndex: number;
  position: Point;
  anchor: Point;
  sourceSize: Size;
  scale: number;
  rotation: number;
  dependsOn?: string[];
  renderParts?: RenderPart[];
  [key: string]: unknown;
}
export interface GameLayout {
  sceneId: string;
  layoutRevision: LayoutRevision;
  geoBlocks: GeoBlock[];
  stickers: StickerPlacement[];
  renderParts?: Record<string, unknown>[];
  renderOrder?: RenderQueueEntry[];
  fixedLayers?: FixedPlacement[];
  [key: string]: unknown;
}
export interface PlacementTicket { stickerId: string; transactionId: number }
export interface BlockProgress {
  blockId: string;
  blockOrder: number;
  placed: number;
  total: number;
  completed: boolean;
}
export interface SessionSnapshot {
  sceneId: string;
  layoutRevision: LayoutRevision;
  revision: number;
  phase: SessionPhase;
  activeBlockId: string | null;
  activeAreaLevel: AreaLevel | null;
  selectedStickerId: string | null;
  pendingPlacement: PlacementTicket | null;
  /** Ready stickers in the active stage; global render order breaks ties. */
  availableStickerIds: string[];
  /** Chronological successful placements, for undo and prefix validation. */
  placedStickerIds: string[];
  /** The whole scene's placed sticker IDs sorted by global placementOrder. */
  renderStickerIds: string[];
  progress: { placed: number; total: number; blocks: BlockProgress[] };
  /** Selection/placement lock. Completed scenes can still allow undo. */
  interactionLocked: boolean;
  canUndo: boolean;
}
export interface SessionSave {
  schemaVersion: 'sticker-session-v1';
  sceneId: string;
  layoutRevision: LayoutRevision;
  placedStickerIds: string[];
  activeBlockId: string | null;
  transitionPending: boolean;
}
export type SessionEventType =
  | 'selected' | 'selection-cancelled' | 'placement-started'
  | 'placement-cancelled' | 'placed' | 'transition-finished'
  | 'undo' | 'restored';
export interface SessionEvent {
  type: SessionEventType;
  revision: number;
  stickerId?: string;
  completedBlockId?: string;
  nextBlockId?: string | null;
}
export type SessionListener = (snapshot: SessionSnapshot, event: SessionEvent) => void;
export interface RestoreResult { ok: boolean; errors: string[] }

const AREA_LEVELS: AreaLevel[] = ['L1', 'L2', 'L3'];
const levelRank = (level: AreaLevel): number => AREA_LEVELS.indexOf(level);
const record = (value: unknown): value is Record<string, unknown> =>
  value !== null && typeof value === 'object' && !Array.isArray(value);
const finite = (value: unknown): value is number =>
  typeof value === 'number' && Number.isFinite(value);
const integer = (value: unknown): value is number =>
  finite(value) && Number.isSafeInteger(value);
const identifier = (value: unknown): value is string =>
  typeof value === 'string' && value.length > 0 && value.trim() === value;
const clone = <T>(value: T): T => JSON.parse(JSON.stringify(value)) as T;

/** Structural and gameplay validation; no engine or filesystem dependency. */
export function validateLayout(value: unknown): string[] {
  const errors: string[] = [];
  if (!record(value)) return ['layout must be an object'];
  if (!identifier(value.sceneId)) errors.push('sceneId must be a nonempty string');
  if (!identifier(value.layoutRevision) && !(integer(value.layoutRevision) && value.layoutRevision >= 0)) {
    errors.push('layoutRevision must be a nonempty string or nonnegative safe integer');
  }
  if (!Array.isArray(value.geoBlocks)) errors.push('geoBlocks must be an array');
  if (!Array.isArray(value.stickers)) errors.push('stickers must be an array');
  if (errors.length) return errors;
  const blockOrders = new Set<number>();
  const blocks = new Map<string, GeoBlock>();
  for (const [index, entry] of Array.from(value.geoBlocks as unknown[]).entries()) {
    const label = `geoBlocks[${index}]`;
    if (!record(entry)) { errors.push(`${label} must be an object`); continue; }
    if (!identifier(entry.blockId)) errors.push(`${label}.blockId must be nonempty`);
    else if (blocks.has(entry.blockId)) errors.push(`duplicate blockId ${entry.blockId}`);
    else blocks.set(entry.blockId, entry as unknown as GeoBlock);
    if (!integer(entry.blockOrder) || entry.blockOrder < 0) {
      errors.push(`${label}.blockOrder must be a nonnegative safe integer`);
    } else if (blockOrders.has(entry.blockOrder)) {
      errors.push(`duplicate blockOrder ${entry.blockOrder}`);
    } else blockOrders.add(entry.blockOrder);
  }
  const stickers = new Map<string, StickerPlacement>();
  const renderOrders = new Set<number>();
  for (const [index, entry] of Array.from(value.stickers as unknown[]).entries()) {
    const label = `stickers[${index}]`;
    if (!record(entry)) { errors.push(`${label} must be an object`); continue; }
    if (!identifier(entry.stickerId)) errors.push(`${label}.stickerId must be nonempty`);
    else if (stickers.has(entry.stickerId)) errors.push(`duplicate stickerId ${entry.stickerId}`);
    else stickers.set(entry.stickerId, entry as unknown as StickerPlacement);
    if (!identifier(entry.geoBlock) || !blocks.has(entry.geoBlock)) {
      errors.push(`${label}.geoBlock must reference an existing block`);
    }
    if (!AREA_LEVELS.includes(entry.areaLevel as AreaLevel)) errors.push(`${label}.areaLevel must be L1, L2 or L3`);
    if (!integer(entry.placementOrder) || entry.placementOrder < 0) {
      errors.push(`${label}.placementOrder must be a nonnegative safe integer`);
    } else if (renderOrders.has(entry.placementOrder)) {
      errors.push(`duplicate placementOrder ${entry.placementOrder}`);
    } else renderOrders.add(entry.placementOrder);
    if (!integer(entry.layerIndex)) errors.push(`${label}.layerIndex must be a safe integer`);
    if (!record(entry.position) || !finite(entry.position.x) || !finite(entry.position.y)) {
      errors.push(`${label}.position must contain finite x and y`);
    }
    if (!record(entry.anchor) || !finite(entry.anchor.x) || !finite(entry.anchor.y)
      || entry.anchor.x < 0 || entry.anchor.x > 1 || entry.anchor.y < 0 || entry.anchor.y > 1) {
      errors.push(`${label}.anchor must contain normalized x and y in [0, 1]`);
    }
    if (!record(entry.sourceSize) || !finite(entry.sourceSize.width) || !finite(entry.sourceSize.height)
      || entry.sourceSize.width <= 0 || entry.sourceSize.height <= 0) {
      errors.push(`${label}.sourceSize must contain positive width and height`);
    }
    if (!finite(entry.scale) || entry.scale <= 0) errors.push(`${label}.scale must be positive and finite`);
    if (!finite(entry.rotation)) errors.push(`${label}.rotation must be finite degrees`);
    if (entry.dependsOn !== undefined && (!Array.isArray(entry.dependsOn)
      || Array.from(entry.dependsOn).some(id => !identifier(id)))) {
      errors.push(`${label}.dependsOn must be an array of sticker IDs`);
    }
  }
  // Avoid operating on malformed references while collecting useful errors.
  if (errors.length) return errors;
  for (const sticker of stickers.values()) {
    const seen = new Set<string>();
    for (const dependencyId of sticker.dependsOn ?? []) {
      if (seen.has(dependencyId)) errors.push(`${sticker.stickerId} has duplicate dependency ${dependencyId}`);
      seen.add(dependencyId);
      const dependency = stickers.get(dependencyId);
      if (!dependency) { errors.push(`${sticker.stickerId} has unknown dependency ${dependencyId}`); continue; }
      if (dependencyId === sticker.stickerId) errors.push(`${sticker.stickerId} depends on itself`);
      const block = blocks.get(sticker.geoBlock)!;
      const dependencyBlock = blocks.get(dependency.geoBlock)!;
      if (dependencyBlock.blockOrder > block.blockOrder) {
        errors.push(`${sticker.stickerId} depends on future block sticker ${dependencyId}`);
      } else if (dependency.geoBlock === sticker.geoBlock && levelRank(dependency.areaLevel) > levelRank(sticker.areaLevel)) {
        errors.push(`${sticker.stickerId} depends on a later areaLevel sticker ${dependencyId}`);
      }
    }
  }
  const visiting = new Set<string>();
  const visited = new Set<string>();
  const walk = (id: string): void => {
    if (visiting.has(id)) { errors.push(`dependency cycle at ${id}`); return; }
    if (visited.has(id)) return;
    visiting.add(id);
    for (const dependency of stickers.get(id)?.dependsOn ?? []) if (stickers.has(dependency)) walk(dependency);
    visiting.delete(id);
    visited.add(id);
  };
  for (const id of stickers.keys()) walk(id);
  return errors;
}
