private async boot(): Promise<void> {
  try {
    this.buildRoot();
    const loading = this.makeLabel(this.ui, '造景贴纸\n正在展开素材…', 24, 340, 100);
    const asset = this.layoutAsset ?? await this.loadJson(this.layoutResource);
    if (!this.alive || !isValid(this.node)) return;
    const errors = validateRenderableLayout(asset.json);
    if (errors.length) throw new Error(errors.join('\n'));
    this.sourceLayout = createLayoutDraft(asset.json as GameLayout);
    this.layout = createLayoutDraft(this.sourceLayout);
    try {
      const active = this.runtimeServices().getItem(`theatre-active-layout:${this.layout.sceneId}`);
      if (active) {
        const parsed = JSON.parse(active) as GameLayout;
        if (parsed.sourceLayoutRevision === this.sourceLayout.layoutRevision && this.isKnownDraft(parsed)) this.layout = parsed;
      }
    } catch { /* The source JSON remains authoritative if an active draft is corrupt. */ }
    this.draft = createLayoutDraft(this.layout);
    this.session = new GameSession(this.layout);
    const paths = new Set<string>([this.scene(this.layout).baseAssetKey]);
    for (const patch of this.scene(this.layout).basePatches ?? []) paths.add(patch.assetKey);
    for (const sticker of this.layout.stickers) {
      paths.add(this.imageKey(sticker));
      for (const part of this.parts(sticker)) paths.add(this.imageKey(part));
    }
    for (const fixed of this.fixed(this.layout)) paths.add(this.imageKey(fixed));
    // A bounded loader keeps resource decoding from spiking on phones.
    // Creator's loose spread transform assumes arrays; preserve Set iteration explicitly.
    const queue = Array.from(paths); let completed = 0;
    await Promise.all(Array.from({ length: Math.min(3, queue.length) }, async () => {
      while (queue.length && this.alive) {
        const path = queue.shift()!;
        await this.loadFrame(path);
        completed++;
        if (isValid(loading.node)) loading.string = `造景贴纸\n正在展开素材 ${completed} / ${paths.size}`;
      }
    }));
    const hitAsset = await this.loadJson(this.hitMetadataResource || `${this.resourcePrefix}/metadata/alpha-hit`);
    const hitData = hitAsset.json as unknown as { schemaVersion: string; masks: Record<string, AlphaMask> };
    if (hitData.schemaVersion !== 'alpha-hit-rle-v1') throw new Error('alpha 点击数据格式不匹配');
    this.hitMasks = new Map(Object.entries(hitData.masks));
    // Native PNG pixels may be 2x; precise picking always uses the unchanged
    // sourceSize logical grid. Validate both grids before accepting a gesture.
    for (const owner of this.layout.stickers) for (const artwork of [owner, ...this.parts(owner)]) {
      const mask = this.hitMasks.get(String(artwork.assetKey));
      if (!mask || mask.width !== artwork.sourceSize.width || mask.height !== artwork.sourceSize.height) {
        throw new Error(`透明点击位图必须保持逻辑 sourceSize：${artwork.assetKey}`);
      }
      this.artworkPixels(artwork, this.frames.get(this.imageKey(artwork))!);
    }
    for (const fixed of this.fixed(this.layout)) this.artworkPixels(fixed, this.frames.get(this.imageKey(fixed))!);
    try { this.toolFrame = await this.loadFrame(`resources/${this.tweezersResource}.png`); }
    catch {
      this.toolFrame = null;
      if (this.referenceMotion()) throw new Error('游戏3动效需要原生镊子 PNG，请核对资源前缀内的镊子路径');
    }
    if (!this.alive || !isValid(this.node)) return;
    loading.node.destroy();
    this.restoreProgress();
    this.unsubscribe = this.session.subscribe((_snapshot, event) => {
      if (['placed', 'undo', 'transition-finished', 'restored'].includes(event.type)) this.persist();
      if (event.type === 'undo' || event.type === 'transition-finished') this.page = 0;
      if (event.type === 'selected' || event.type === 'selection-cancelled') {
        this.drawTray(); this.updateStatus(); this.paintShadow();
      } else if (event.type === 'placement-started' || event.type === 'placement-cancelled') {
        if (this.shadow) this.shadow.active = false;
        this.updateStatus();
      } else if (this.busy) {
        this.paintWorld(); this.updateStatus();
      } else this.refresh();
    });
    this.booted = true;
    this.relayout();
    this.setCamera(this.cameraForBlock(this.session.getSnapshot().activeBlockId));
    this.refresh();
    if (this.session.getSnapshot().phase === 'transitioning') void this.runTour();
  } catch (error) {
    console.error('[TheatreGame] boot failed', error);
    if (this.alive && this.ui && isValid(this.ui)) {
      this.destroyChildren(this.ui);
      this.makeLabel(this.ui, `素材尚未就绪\n${String(error)}\n请核对 resources 导入路径。`, 18, 340, 240);
    }
  }
}

private buildRoot(): void {
  this.root = this.makeNode(this.node, 'TheatreRoot', view.getVisibleSize().width, view.getVisibleSize().height);
  const stretch = this.root.addComponent(Widget);
  stretch.isAlignTop = stretch.isAlignBottom = stretch.isAlignLeft = stretch.isAlignRight = true;
  stretch.top = stretch.bottom = stretch.left = stretch.right = 0;
  this.ui = this.makeNode(this.root, 'SafeContent', 390, 844);
  const widget = this.ui.addComponent(Widget);
  widget.isAlignTop = widget.isAlignBottom = widget.isAlignLeft = widget.isAlignRight = true;
  widget.top = widget.bottom = widget.left = widget.right = 0;
