private paintShadow(): void {
  if (this.shadow) this.shadow.active = false;
  this.shadow = null;
  if (this.editing || this.busy || this.overview) return;
  const id = this.session.getSnapshot().selectedStickerId;
  if (!id) return;
  const owner = this.byId(id); const node = this.preparePaper(id).shadow;
  node.active = true;
  const point = transformedPoint(owner, { x: 0, y: 0 });
  node.setPosition(point.x + 2, -point.y - 2); node.setScale(owner.scale, owner.scale, 1);
  node.angle = -owner.rotation;
  // Anchor to real global render nodes, not a raw count of children: inactive
  // cached paper strips/shadows also live in World. The target silhouette sits
  // above earlier supports and below the owner's first part / later foreground.
  let following: Node | undefined; let followingOrder = Infinity;
  let previous = this.sceneNodes.get('base'); let previousOrder = -Infinity;
  for (const entry of this.liveLayout().renderOrder ?? []) {
    const rendered = this.sceneNodes.get(entry.kind === 'fixed' ? `fixed:${entry.fixedId}` : `part:${entry.partId}`);
    if (!rendered) continue;
    if (entry.placementOrder >= owner.placementOrder && entry.placementOrder < followingOrder) {
      following = rendered; followingOrder = entry.placementOrder;
    } else if (entry.placementOrder < owner.placementOrder && entry.placementOrder > previousOrder) {
      previous = rendered; previousOrder = entry.placementOrder;
    }
  }
  const anchor = following ?? previous;
  if (anchor) {
    const insertion = anchor.getSiblingIndex() + (following ? 0 : 1);
    node.setSiblingIndex(insertion - (node.getSiblingIndex() < insertion ? 1 : 0));
  }
  this.shadow = node;
}

