export class GameSession {
  private readonly layout: GameLayout;
  private readonly blocks: GeoBlock[];
  private readonly stickers: Map<string, StickerPlacement>;
  private readonly blockStickers: Map<string, StickerPlacement[]>;
  private readonly listeners = new Set<SessionListener>();
  private history: string[] = [];
  private placed = new Set<string>();
  private blockIndex = 0;
  private phase: SessionPhase = 'playing';
  private selected: string | null = null;
  private pending: PlacementTicket | null = null;
  private revision = 0;
  private transaction = 0;

  constructor(layout: GameLayout) {
    assertLayout(layout);
    this.layout = clone(layout);
    this.blocks = [...this.layout.geoBlocks].sort((a, b) => a.blockOrder - b.blockOrder);
    this.stickers = new Map(this.layout.stickers.map(sticker => [sticker.stickerId, sticker]));
    this.blockStickers = new Map(this.blocks.map(block => [block.blockId,
      this.layout.stickers.filter(sticker => sticker.geoBlock === block.blockId)
        .sort((a, b) => a.placementOrder - b.placementOrder)]));
    this.blockIndex = this.skipEmptyBlocks(0);
    if (this.blockIndex >= this.blocks.length) this.phase = 'completed';
  }

  /** A copy: renderer/editor mutation cannot silently modify a running session. */
  getLayout(): GameLayout { return clone(this.layout); }

  subscribe(listener: SessionListener): () => void {
    this.listeners.add(listener);
    return () => { this.listeners.delete(listener); };
  }

  getSnapshot(): SessionSnapshot {
    const activeBlockId = this.blocks[this.blockIndex]?.blockId ?? null;
    const activeAreaLevel = this.phase === 'playing' || this.phase === 'placing'
      ? this.activeLevel(this.blockIndex, this.placed) : null;
    const blocks: BlockProgress[] = this.blocks.map(block => {
      const members = this.blockStickers.get(block.blockId)!;
      const placed = members.filter(sticker => this.placed.has(sticker.stickerId)).length;
      return { blockId: block.blockId, blockOrder: block.blockOrder, placed,
        total: members.length, completed: placed === members.length };
    });
    return {
      sceneId: this.layout.sceneId, layoutRevision: this.layout.layoutRevision,
      revision: this.revision, phase: this.phase, activeBlockId, activeAreaLevel,
      selectedStickerId: this.selected,
      pendingPlacement: this.pending ? { ...this.pending } : null,
      availableStickerIds: this.phase === 'playing' ? this.readyIds() : [],
      placedStickerIds: [...this.history],
      renderStickerIds: this.layout.stickers.filter(sticker => this.placed.has(sticker.stickerId))
        .sort((a, b) => a.placementOrder - b.placementOrder).map(sticker => sticker.stickerId),
      progress: { placed: this.history.length, total: this.layout.stickers.length, blocks },
      interactionLocked: this.phase !== 'playing',
      canUndo: this.phase !== 'placing' && this.phase !== 'transitioning' && this.history.length > 0,
    };
  }

  select(stickerId: string): boolean {
    if (this.phase !== 'playing' || !this.readyIds().includes(stickerId)) return false;
    if (this.selected === stickerId) return true;
    this.selected = stickerId;
    this.emit({ type: 'selected', stickerId });
    return true;
  }

  cancelSelection(): boolean {
    if (this.phase !== 'playing' || this.selected === null) return false;
    const stickerId = this.selected;
    this.selected = null;
    this.emit({ type: 'selection-cancelled', stickerId });
    return true;
  }

  beginPlacement(stickerId: string): PlacementTicket | null {
    if (this.phase !== 'playing' || this.selected !== stickerId || !this.readyIds().includes(stickerId)) return null;
    this.pending = { stickerId, transactionId: ++this.transaction };
    this.phase = 'placing';
    this.emit({ type: 'placement-started', stickerId });
    return { ...this.pending };
  }

  cancelPlacement(ticket?: PlacementTicket): boolean {
    if (this.phase !== 'placing' || !this.pending || (ticket && !this.matchesTicket(ticket))) return false;
    const stickerId = this.pending.stickerId;
    this.pending = null;
    this.phase = 'playing';
    this.emit({ type: 'placement-cancelled', stickerId });
    return true;
  }

  /** Only a valid live animation ticket can add progress; duplicate callbacks do nothing. */
  commitPlacement(ticket: PlacementTicket): boolean {
    if (this.phase !== 'placing' || !this.matchesTicket(ticket)) return false;
    const stickerId = this.pending!.stickerId;
    this.placed.add(stickerId);
    this.history.push(stickerId);
    this.pending = null;
    this.selected = null;
    const completedBlockId = this.activeLevel(this.blockIndex, this.placed) === null
      ? this.blocks[this.blockIndex].blockId : undefined;
    this.phase = completedBlockId ? 'transitioning' : 'playing';
    this.emit({ type: 'placed', stickerId, completedBlockId });
    return true;
  }

  /** Called after celebration AND camera motion. Also finalizes the last block. */
  finishTransition(): boolean {
    if (this.phase !== 'transitioning') return false;
    const completedBlockId = this.blocks[this.blockIndex].blockId;
    this.blockIndex = this.skipEmptyBlocks(this.blockIndex + 1);
    this.phase = this.blockIndex < this.blocks.length ? 'playing' : 'completed';
    this.emit({ type: 'transition-finished', completedBlockId,
      nextBlockId: this.blocks[this.blockIndex]?.blockId ?? null });
    return true;
  }

  /** Locked during animations. After transition, undo can return to an earlier block. */
  undo(): boolean {
    if (this.phase === 'placing' || this.phase === 'transitioning' || this.history.length === 0) return false;
    const stickerId = this.history[this.history.length - 1];
    const history = this.history.slice(0, -1);
    const replay = this.replay(history);
    this.history = history;
    this.placed = replay.placed;
    this.blockIndex = replay.nextBlockIndex;
    this.phase = this.blockIndex < this.blocks.length ? 'playing' : 'completed';
    this.selected = null;
    this.pending = null;
    this.transaction++;
    this.emit({ type: 'undo', stickerId });
    return true;
  }

  exportSave(): SessionSave {
    return { schemaVersion: 'sticker-session-v1', sceneId: this.layout.sceneId,
      layoutRevision: this.layout.layoutRevision, placedStickerIds: [...this.history],
      activeBlockId: this.blocks[this.blockIndex]?.blockId ?? null,
      transitionPending: this.phase === 'transitioning' };
  }

  /** Atomic: rejected/corrupt/stale-layout saves leave current state untouched. */
  restore(value: unknown): RestoreResult {
    const errors: string[] = [];
    if (!record(value)) return { ok: false, errors: ['save must be an object'] };
    if (value.schemaVersion !== 'sticker-session-v1') errors.push('unsupported save schemaVersion');
    if (value.sceneId !== this.layout.sceneId) errors.push('save sceneId does not match');
    if (value.layoutRevision !== this.layout.layoutRevision) errors.push('save layoutRevision does not match');
    if (!Array.isArray(value.placedStickerIds)
      || Array.from(value.placedStickerIds).some(id => !identifier(id))) {
      errors.push('save placedStickerIds must be a dense array of sticker IDs');
    }
    if (typeof value.transitionPending !== 'boolean') errors.push('save transitionPending must be boolean');
    if (value.activeBlockId !== null && !identifier(value.activeBlockId)) errors.push('save activeBlockId must be a block ID or null');
    if (errors.length) return { ok: false, errors };
    const history = [...value.placedStickerIds as string[]];
    const replay = this.replay(history);
    errors.push(...replay.errors);
    let blockIndex = replay.nextBlockIndex;
    if (value.transitionPending) {
      if (replay.lastCompletedBlockIndex === null) errors.push('pending transition requires the last placement to complete a block');
      else blockIndex = replay.lastCompletedBlockIndex;
    }
    const expectedBlockId = this.blocks[blockIndex]?.blockId ?? null;
    if (value.activeBlockId !== expectedBlockId) errors.push('save activeBlockId is inconsistent with placement history');
    if (errors.length) return { ok: false, errors };
    this.history = history;
    this.placed = replay.placed;
    this.blockIndex = blockIndex;
    this.phase = value.transitionPending ? 'transitioning'
      : this.blockIndex < this.blocks.length ? 'playing' : 'completed';
    this.selected = null;
    this.pending = null;
    this.transaction++;
    this.emit({ type: 'restored' });
    return { ok: true, errors: [] };
  }

  private skipEmptyBlocks(start: number): number {
    let index = start;
    while (index < this.blocks.length && this.blockStickers.get(this.blocks[index].blockId)!.length === 0) index++;
    return index;
  }

  private activeLevel(blockIndex: number, placed: Set<string>): AreaLevel | null {
    const members = this.blockStickers.get(this.blocks[blockIndex]?.blockId ?? '') ?? [];
    return AREA_LEVELS.find(level => members.some(sticker => sticker.areaLevel === level && !placed.has(sticker.stickerId))) ?? null;
  }

  private readyIds(): string[] {
    const level = this.activeLevel(this.blockIndex, this.placed);
    return (this.blockStickers.get(this.blocks[this.blockIndex]?.blockId ?? '') ?? [])
      .filter(sticker => sticker.areaLevel === level && !this.placed.has(sticker.stickerId)
        && (sticker.dependsOn ?? []).every(id => this.placed.has(id)))
      .map(sticker => sticker.stickerId);
  }

  private matchesTicket(ticket: PlacementTicket): boolean {
    return record(ticket) && !!this.pending && ticket.stickerId === this.pending.stickerId
      && ticket.transactionId === this.pending.transactionId;
  }

  private replay(history: string[]): ReplayedHistory {
    const placed = new Set<string>();
    let nextBlockIndex = this.skipEmptyBlocks(0);
    let lastCompletedBlockIndex: number | null = null;
    const errors: string[] = [];
    for (const [index, id] of history.entries()) {
      const sticker = this.stickers.get(id);
      if (!sticker) { errors.push(`history[${index}] has unknown sticker ${id}`); break; }
      if (placed.has(id)) { errors.push(`history[${index}] repeats sticker ${id}`); break; }
      if (sticker.geoBlock !== this.blocks[nextBlockIndex]?.blockId) {
        errors.push(`history[${index}] enters a block before the previous block is complete`); break;
      }
      if (sticker.areaLevel !== this.activeLevel(nextBlockIndex, placed)) {
        errors.push(`history[${index}] violates L1/L2/L3 stage order`); break;
      }
      if (!(sticker.dependsOn ?? []).every(dependency => placed.has(dependency))) {
        errors.push(`history[${index}] violates sticker dependencies`); break;
      }
      placed.add(id);
      lastCompletedBlockIndex = null;
      if (this.activeLevel(nextBlockIndex, placed) === null) {
        lastCompletedBlockIndex = nextBlockIndex;
        nextBlockIndex = this.skipEmptyBlocks(nextBlockIndex + 1);
      }
    }
    return { placed, nextBlockIndex, lastCompletedBlockIndex, errors };
  }

  private emit(event: Omit<SessionEvent, 'revision'>): void {
    this.revision++;
    const completeEvent: SessionEvent = { ...event, revision: this.revision };
    // Capture once before listeners: a listener may synchronously perform another action.
    const snapshot = this.getSnapshot();
    for (const listener of Array.from(this.listeners)) listener(clone(snapshot), { ...completeEvent });
  }
}

export type StickerDraftPatch = Partial<Pick<StickerPlacement,
  'position' | 'scale' | 'rotation' | 'areaLevel' | 'geoBlock' | 'layerIndex' | 'anchor'>>;

/** Pure JSON draft helpers. They never load, cut, transform or write raster files. */
export function createLayoutDraft(layout: GameLayout): GameLayout {
  assertLayout(layout);
  return clone(layout);
}

export function patchStickerDraft(layout: GameLayout, stickerId: string, patch: StickerDraftPatch): GameLayout {
  const draft = createLayoutDraft(layout);
  const sticker = draft.stickers.find(entry => entry.stickerId === stickerId);
  if (!sticker) throw new Error(`Unknown sticker ${stickerId}`);
  const allowed = new Set(['position', 'scale', 'rotation', 'areaLevel', 'geoBlock', 'layerIndex', 'anchor']);
  for (const key of Object.keys(patch)) {
    if (!allowed.has(key)) throw new Error(`Unsupported editable sticker field ${key}`);
    (sticker as Record<string, unknown>)[key] = clone((patch as Record<string, unknown>)[key]);
  }
  assertLayout(draft);
  refreshPlayMetadata(draft);
  return draft;
}

