  constructor(layout: GameLayout) {
    assertLayout(layout);
    this.layout = clone(layout);
    this.blocks = [...this.layout.geoBlocks].sort((a, b) => a.blockOrder - b.blockOrder);
    this.stickers = new Map(this.layout.stickers.map(sticker => [sticker.stickerId, sticker]));
    this.blockStickers = new Map(this.blocks.map(block => [block.blockId,
      this.layout.stickers.filter(sticker => sticker.geoBlock === block.blockId)
        .sort((a, b) => a.placementOrder - b.placementOrder)]));
    this.blockIndex = this.skipCompletedBlocks(0, this.placed);
    if (this.blockIndex >= this.blocks.length) this.phase = 'completed';
  }

  /** A copy: renderer/editor mutation cannot silently modify a running session. */
  getLayout(): GameLayout { return clone(this.layout); }

  subscribe(listener: SessionListener): () => void {
    this.listeners.add(listener);
    return () => { this.listeners.delete(listener); };
