    const framing = supports.map(owner => {
      const focus = owner.cameraFocusBounds as Bounds | undefined;
      if (!this.editing && owner.spatialRole === 'shared-backdrop' && focus
        && [focus.x, focus.y, focus.width, focus.height].every(Number.isFinite)
        && focus.width > 0 && focus.height > 0) {
        return { position: { x: focus.x, y: focus.y }, sourceSize: { width: focus.width, height: focus.height },
          anchor: { x: 0, y: 0 }, scale: 1, rotation: 0 };
      }
