/** Safe-area UI units only. Artwork always keeps its source aspect ratio. */
export interface ViewportRect { x: number; y: number; width: number; height: number }
export interface TheatreViewportLayout {
  width: number; height: number; unit: number; mode: 'bottom-tray' | 'side-tray';
  header: ViewportRect; board: ViewportRect; tray: ViewportRect;
}
export interface StickerTrayLayout {
  columns: number; rows: number; cardWidth: number; cardHeight: number;
  columnStep: number; firstCardY: number; rowStep: number; pagerY: number;
  editorColumns: number; firstEditorY: number; editorRowStep: number; actionsY: number;
}
const clamp = (value: number, min: number, max: number): number => Math.max(min, Math.min(max, value));

/** Portrait keeps the familiar paper shelf; wide screens move it beside the board. */
export function theatreViewportLayout(width: number, height: number, editing: boolean): TheatreViewportLayout {
  const w = Number.isFinite(width) && width > 0 ? width : 390;
  const h = Number.isFinite(height) && height > 0 ? height : 844;
  const side = w >= 640 && w >= h * 1.1;
  // Width alone made a desktop header/shelf consume nearly all available height.
  const u = side ? clamp(Math.min(w / 980, h / 760), 0.7, 1.25)
    : clamp(Math.min(w / 390, h / 844), 0.7, 1.25);
  const headerH = 126 * u;
  const header = { x: 0, y: h / 2 - headerH / 2, width: w - 28 * u, height: headerH };
  if (side) {
    const margin = 12 * u; const trayW = 304 * u;
    const boardH = Math.max(1, h - headerH - 26 * u);
    // A very wide camera shows neighbouring regions even while fitting the
    // active tall corner. Keep a portrait-shaped play window and centre it.
    const boardW = Math.max(1, Math.min(w - 3 * margin - trayW, boardH * 0.95));
    const groupW = boardW + margin + trayW;
    header.width = Math.min(header.width, groupW);
    const y = h / 2 - headerH - 10 * u - boardH / 2;
    return { width: w, height: h, unit: u, mode: 'side-tray', header,
      board: { x: -groupW / 2 + boardW / 2, y, width: boardW, height: boardH },
      tray: { x: groupW / 2 - trayW / 2, y, width: trayW, height: boardH } };
  }
  const trayH = (editing ? 274 : 214) * u;
  const boardH = Math.max(1, h - headerH - trayH - 28 * u);
  const boardW = w >= 640 ? Math.min(w - 24 * u, boardH * 0.95) : w - 24 * u;
  return { width: w, height: h, unit: u, mode: 'bottom-tray', header,
    board: { x: 0, y: h / 2 - headerH - 14 * u - boardH / 2, width: boardW, height: boardH },
    tray: { x: 0, y: -h / 2 + trayH / 2 + 7 * u, width: w - 24 * u, height: trayH } };
}

/** Card event nodes, artwork and editor controls share these local tray positions. */
export function stickerTrayLayout(viewport: TheatreViewportLayout, editing: boolean): StickerTrayLayout {
  const u = viewport.unit; const side = viewport.mode === 'side-tray';
  const columns = side ? 2 : 4; const rows = side ? 2 : 1;
  const columnStep = (viewport.tray.width - 24 * u) / columns;
  const gap = 8 * u;
  const cardHeight = side ? Math.max(1, Math.min(150 * u,
    (viewport.tray.height - (editing ? 202 : 94) * u - gap) / 2)) : 112 * u;
  const firstCardY = viewport.tray.height / 2 - 42 * u - cardHeight / 2;
  const pagerY = firstCardY - (rows - 1) * (cardHeight + gap) - cardHeight / 2 - 23 * u;
  return { columns, rows, cardWidth: columnStep - 7 * u, cardHeight, columnStep,
    firstCardY, rowStep: cardHeight + gap, pagerY,
    editorColumns: side ? 3 : 6, firstEditorY: pagerY - (side ? 32 : 34) * u,
    editorRowStep: 32 * u, actionsY: pagerY - (side ? 104 : 70) * u };
}

