    pngs = sorted(p for p in extracted.rglob('*.png') if any(p.relative_to(extracted).as_posix().startswith(s) for s in material_prefixes))
    with zipfile.ZipFile(old_zip) as archive:
        old = {name.removeprefix(prefix + '/') for name in archive.namelist()
               if name.startswith(prefix + '/') and name.endswith('.png')
