/** Source origin is top-left, UI origin is board center and positive Y points up. */
export function fitCamera(bounds: Bounds, viewport: { width: number; height: number }, padding = 16): CameraPose {
  const scale = Math.max(0.001, Math.min(Math.max(1, viewport.width - padding * 2) / bounds.width,
    Math.max(1, viewport.height - padding * 2) / bounds.height));
  return { x: -(bounds.x + bounds.width / 2) * scale,
    y: (bounds.y + bounds.height / 2) * scale, scale };
